        engineeringData: { blockDesign: "Open-deck Cast-Iron block. The M44 is a highly refined evolution of the 16-valve M42. It increased displacement from 1.8L to 1.9L and adopted roller rocker arms to reduce valvetrain friction significantly.", crankshaft: "Cast Iron, supported by 5 main bearings. Switched from the M42's forged crank to save weight, but remains highly durable.", pistonSpeed: "14.3 m/s @ 6000 RPM.", alternator: "90A Bosch (V-belt driven).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M9.", crankMainJournal: "55.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.62." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for a 10.0:1 compression ratio.", intakePortFlow: "16-valve DOHC design. The M44 head flows incredibly well and uses roller rockers instead of the M42's friction buckets, making it much quieter and more efficient.", valveSizes: "Intake: 33.0 mm / Exhaust: 30.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "240° symmetrical duration. Driven by a single-row timing chain.", lifterType: "Hydraulic Tappets with roller rocker arms.", specialFeature: "Features a DISA (Dual Resonance Intake System) valve inside the intake manifold. It changes the effective length of the intake runners based on RPM to optimize both low-end torque and high-end power." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven rotor pump integrated into the front cover.", thermostatOpening: "95°C Mechanical.", oilCooler: "None equipped." }, fuelSystem: { systemType: "Bosch Motronic M5.2 Port Injection. Utilizes a modern MAF sensor instead of a restrictive AFM flapper.", maxPressure: "3.0 Bar.", injectors: "4x Bosch EV1 Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "350 Nm (Block limits).", maxSafePowerStock: "220 hp (Requires custom Turbo setup).", maxSafeRPM: "6500 RPM.", weakestLink: "Plastic Cooling Components, DISA Valve Flap, Cast Crankshaft (compared to M42)." }, electrical: { coils: "Wasted spark coil pack module.", ecu: "Bosch Motronic M5.2." } },
        recommendedParts: { description: "Crucial maintenance parts to keep the reliable M44 1.9L engine and the E36 chassis functioning perfectly.", parts: [ { category: "Water Pump", brand: "Saleri / Hepu", note: "CRITICAL: Replace proactively. Ensure the replacement uses a metal or composite impeller, not original plastic." }, { category: "Thermostat Housing", brand: "Meyle / Uro", note: "CRITICAL: Replace the fragile plastic factory housing with aluminum to prevent shattering." }, { category: "Coolant Pipe (Under Intake)", brand: "Genuine BMW", note: "CRITICAL: Hard plastic pipe degrades and shatters; replace proactively to prevent sudden coolant dumps." }, { category: "DISA Valve Rebuild Kit", brand: "X8R / German Auto Solutions", note: "Rebuild the rattling flap mechanism with an aluminum flap and titanium pin to prevent engine ingestion." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "Fixes the most common severe oil leak on the M44 block." }, { category: "Mass Air Flow Sensor", brand: "Bosch Genuine", note: "DO NOT use cheap aftermarket MAF sensors; they will cause severe drivability issues." }, { category: "Rear Shock Mounts (RSMs)", brand: "Meyle HD", note: "Install with reinforcement plates to protect the chassis." }, { category: "Rear Trailing Arm Bushings", brand: "Lemförder / Powerflex", note: "Replace immediately if the rear end feels unstable or disconnected during cornering." } ] },
