          fluidsAndDrivetrain: [ { interval: "40,000 km", timeLimit: "4 years", task: "Manual Gearbox Oil", details: "Drain and refill the Getrag 250 with ATF or MTF.", parts: ["1.2L ATF Dexron II"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Rear Differential Oil", details: "Extract and refill the classic E36 rear differential.", parts: ["0.9L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 fluid. Crucial as old rubber lines absorb moisture rapidly.", parts: ["1.0L DOT 4"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Shift Linkage Rebuild", details: "Replace the plastic and rubber bushings in the gear selector rod to fix sloppy shifter feel.", parts: ["Bushing Rebuild Kit"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "100 EUR" } ],
          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "Use high-quality 5W-40 Synthetic. Clean oil is vital for the hydraulic lifters and timing chain health.", parts: ["5.0L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "65 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Fuel Filter", details: "Replace the high-pressure fuel filter to protect the Bosch EV1 injectors.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
          ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "DISA Valve Rebuild", details: "CRITICAL: Remove the DISA valve from the intake manifold. If the flap rattles or the pin is loose, rebuild it immediately to prevent engine destruction.", parts: ["DISA Rebuild Kit"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Replace copper spark plugs.", parts: ["4x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket", details: "Remove the oil filter housing and replace the rubber profile gasket when massive oil leaks appear down the side of the block.", parts: ["Elring Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "30 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "PCV Valve Replacement", details: "Replace the crankcase vent valve and hoses if you hear a loud whistle or experience a surging idle.", parts: ["PCV Valve", "Hoses"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" } ],
          preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "10 years", task: "Front Control Arm Bushings (FCAB)", details: "Replace the rear lollipops (M3 offset bushings recommended) to cure the E36 shimmy under braking.", parts: ["FCAB Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Rear Trailing Arm Bushings (RTAB)", details: "Replace the massive rubber trailing arm mounts to restore rear chassis stability and alignment geometry.", parts: ["RTAB Bushings"], importance: "High", laborDifficulty: "Expert", estimatedCost: "250 EUR" }, { interval: "Immediately", timeLimit: "Unlimited", task: "RSM Reinforcement", details: "Install steel reinforcement plates above the rear shock mounts to prevent the shocks punching through the trunk floor.", parts: ["Meyle HD RSMs", "Z3 Plates"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "V-Belts & Tensioners", details: "Replace the serpentine belts and inspect the idler pulleys for bearing noise.", parts: ["V-Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" } ],
