          engineMechanical: [ { interval: "250,000 km", timeLimit: "Unlimited", task: "Timing Chain Inspection", details: "The M44 chain is incredibly robust. Listen for cold start rattling at extreme high mileage to indicate worn guides.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Boot Replacement", details: "Replace the large rubber intake boot. Cracks allow unmetered air and destroy idle quality.", parts: ["Intake Boot"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" } ]
