        engineeringData: { blockDesign: "Open-deck Aluminum alloy block. The N40 was essentially a stripped-down N42 designed for specific tax markets, removing the complex Valvetronic system but retaining the fragile chain guides and leaking vacuum pump.", crankshaft: "Forged Steel, supported by 5 main bearings. Features twin balance shafts in the oil pan to eliminate 4-cylinder vibrations.", pistonSpeed: "14.3 m/s @ 6000 RPM.", alternator: "110A Bosch or Valeo (V-belt driven).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "140 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.72." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for a 10.2:1 compression ratio.", intakePortFlow: "16-valve DOHC design. Crucially, the N40 uses a traditional throttle butterfly instead of the complex Valvetronic variable lift system.", valveSizes: "Intake: 32.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "5.0 mm (Extremely thin, leading to rapid valve stem seal failure).", camshaftDuration: "Variable. Controlled by Dual VANOS.", lifterType: "Hydraulic Tappets.", specialFeature: "Dual VANOS. This hydraulically actuated unit shifts the phase of both the intake and exhaust camshafts to significantly improve mid-range torque and emissions." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven rotor pump integrated into the balance shaft module.", thermostatOpening: "105°C Electronic map-controlled (Runs extremely hot for emissions).", oilCooler: "Coolant-to-oil heat exchanger mounted to the oil filter housing." }, fuelSystem: { systemType: "Bosch DME ME9.2 Port Injection.", maxPressure: "3.5 Bar.", injectors: "4x Bosch EV14 Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "250 Nm (Block limits).", maxSafePowerStock: "160 hp (Tuning is highly discouraged).", maxSafeRPM: "6500 RPM.", weakestLink: "Timing Chain Guides, Valve Stem Seals, Vacuum Pump, Plastic Cooling Components." }, electrical: { coils: "Individual Coil Pack system (Coil-on-Plug) pencil-style coils.", ecu: "Bosch DME ME9.2." } },
        recommendedParts: { description: "Crucial maintenance parts to keep the fragile N40 engine from destroying itself.", parts: [ { category: "Timing Chain Tensioner", brand: "Genuine BMW", note: "CRITICAL: Upgrade to the newer, longer tensioner immediately." }, { category: "Timing Chain Kit", brand: "Febi / INA", note: "CRITICAL: Replace the chain, guides, and sprockets entirely at 150k km." }, { category: "Valve Stem Seals", brand: "Elring / Victor Reinz", note: "CRITICAL: Required if the engine burns oil or smokes at idle." }, { category: "Vacuum Pump Reseal Kit", brand: "Elring", note: "Fixes the severe oil leak onto the hot exhaust manifold." }, { category: "Coolant Expansion Tank", brand: "Behr / Modine", note: "CRITICAL: The factory E46 tanks split down the seam. Replace proactively." }, { category: "Water Pump", brand: "Saleri / Hepu", note: "Replace proactively. Ensure the replacement uses a metal or composite impeller." }, { category: "CCV / PCV Valve Kit", brand: "Genuine BMW (Cold Climate)", note: "Replace the entire oil separator system and hoses to cure vacuum leaks." }, { category: "Valve Cover Gasket", brand: "Elring / Victor Reinz", note: "Rubber gasket; replace if leaking oil." } ] },
