        engineeringData: { blockDesign: "Open-deck Cast-Iron block. The M43TUB19 is the final, most refined iteration of the M43 family, utilizing balance shafts for incredible smoothness and a robust timing chain.", crankshaft: "Forged Steel, supported by 5 main bearings. Features balance shafts to eliminate 4-cylinder vibrations.", pistonSpeed: "14.3 m/s @ 6000 RPM.", alternator: "90A Bosch (V-belt driven).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M9.", crankMainJournal: "55.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.70." }, cylinderHead: { combustionChamberVol: "Wedge-shaped combustion chambers.", intakePortFlow: "8-valve SOHC crossflow design. Features roller-rocker arms that dramatically reduce friction and wear. The 8-valve design restricts high-RPM breathing but provides excellent low-end torque for city driving.", valveSizes: "Intake: 42.0 mm / Exhaust: 36.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "244° symmetrical duration. Driven by a robust single-row timing chain.", lifterType: "Hydraulic Tappets with roller rocker arms.", specialFeature: "Features a DISA (Dual Resonance Intake System) valve inside the intake manifold. It changes the effective length of the intake runners based on RPM to optimize both low-end torque and high-end power." }, oilAndCooling: { oilSquirters: "No under-piston cooling jets.", oilPumpType: "Chain-driven rotor pump integrated into the front cover.", thermostatOpening: "105°C Electronic map-controlled (Runs extremely hot for emissions).", oilCooler: "None equipped." }, fuelSystem: { systemType: "Bosch BMS 46 Port Injection.", maxPressure: "3.0 Bar.", injectors: "4x Bosch EV1 Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "350 Nm (Block limits).", maxSafePowerStock: "250 hp (Requires custom Turbo setup).", maxSafeRPM: "6500 RPM.", weakestLink: "Plastic Cooling Components (Pipe under intake, Expansion Tank), Map-Controlled Thermostat, DISA Valve Flap." }, electrical: { coils: "Wasted spark coil pack module.", ecu: "Bosch BMS 46." } },
        recommendedParts: { description: "Crucial maintenance parts to keep the reliable 1.9L engine and the E46 chassis functioning perfectly.", parts: [ { category: "Water Pump", brand: "Saleri / Hepu", note: "CRITICAL: Replace proactively. Ensure the replacement uses a metal or composite impeller, not original plastic." }, { category: "Coolant Expansion Tank", brand: "Behr / Modine", note: "CRITICAL: The factory E46 tanks split down the seam. Replace every 100k km." }, { category: "Map-Controlled Thermostat", brand: "Behr / Wahler", note: "CRITICAL: Replace proactively. The internal heater element fails frequently, causing cooling system chaos." }, { category: "Coolant Pipe (Under Intake)", brand: "Genuine BMW", note: "CRITICAL: Hard plastic pipe degrades and shatters; replace proactively to prevent sudden coolant dumps." }, { category: "DISA Valve Rebuild Kit", brand: "X8R / German Auto Solutions", note: "Rebuild the rattling flap mechanism with an aluminum flap and titanium pin to prevent engine ingestion." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "Fixes the most common severe oil leak on the M43 block." }, { category: "Mass Air Flow Sensor", brand: "Bosch Genuine", note: "DO NOT use cheap aftermarket MAF sensors; they will cause severe drivability issues." }, { category: "Front Control Arm Bushings", brand: "Lemförder / Meyle HD", note: "The notorious E46 FCABs fail frequently; Meyle HD solid rubber is a great upgrade." } ] },
