          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "Use high-quality 5W-40 Synthetic (LL-01). Clean oil is vital for the hydraulic lifters and timing chain health.", parts: ["4.0L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "65 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Fuel Filter", details: "Replace the high-pressure fuel filter.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the pollen filter under the cowl to ensure proper HVAC airflow.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
          ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "DISA Valve Rebuild", details: "CRITICAL: Remove the DISA valve from the intake manifold. If the flap rattles or the pin is loose, rebuild it immediately.", parts: ["DISA Rebuild Kit"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Replace copper spark plugs.", parts: ["4x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket", details: "Remove the oil filter housing and replace the rubber profile gasket when massive oil leaks appear down the side of the block.", parts: ["Elring Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "30 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "PCV Valve Replacement", details: "Replace the crankcase vent valve and hoses if you hear a loud whistle or experience a surging idle.", parts: ["PCV Valve", "Hoses"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Valve Cover Gasket", details: "Replace the valve cover gasket to prevent oil leaking onto the exhaust manifold.", parts: ["Elring Gasket"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
          preventiveAndSuspension: [ { interval: "60,000 km", timeLimit: "8 years", task: "Front Control Arm Bushings (FCAB)", details: "CRITICAL E46 FLAW: Replace the fluid-filled FCABs with solid rubber (Meyle HD) or polyurethane to cure steering wheel shimmy under braking.", parts: ["FCAB Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Rear Trailing Arm Bushings (RTAB)", details: "Replace the massive rubber trailing arm mounts to restore rear chassis stability and alignment geometry.", parts: ["RTAB Bushings"], importance: "High", laborDifficulty: "Expert", estimatedCost: "250 EUR" }, { interval: "Immediately", timeLimit: "Unlimited", task: "RSM Reinforcement", details: "Install steel reinforcement plates above the rear shock mounts to prevent the shocks punching through the trunk.", parts: ["Meyle HD RSMs", "Reinforcement Plates"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "V-Belts & Tensioners", details: "Replace the serpentine belts and inspect the idler pulleys for bearing noise.", parts: ["V-Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" } ],
          coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "Drain and refill the cast-iron block with classic blue/green silicate-based coolant to prevent rust.", parts: ["6.5L G48 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Cooling System Overhaul", details: "CRITICAL: Replace the water pump, electronic thermostat, expansion tank, and the notorious plastic coolant pipe running under the intake manifold.", parts: ["Water Pump", "Thermostat", "Expansion Tank", "Coolant Pipe"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Fan Clutch Replacement", details: "Replace the viscous fan clutch. If it fails, the engine will rapidly overheat in traffic.", parts: ["Viscous Fan Clutch"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" } ],
          engineMechanical: [ { interval: "250,000 km", timeLimit: "Unlimited", task: "Timing Chain Inspection", details: "The M43 chain is incredibly robust. Listen for cold start rattling at extreme high mileage to indicate worn guides.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Boot Replacement", details: "Replace the large rubber intake boot. Cracks allow unmetered air and destroy idle quality.", parts: ["Intake Boot"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" } ]
