          engineMechanical: [ { interval: "150,000 km", timeLimit: "Unlimited", task: "Valvetronic Sensor Check", details: "Pull the plug on the eccentric shaft sensor. If it is full of oil, the sensor has failed internally and must be replaced.", parts: ["Eccentric Shaft Sensor"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Dual VANOS Solenoids", details: "Remove and clean the VANOS solenoids. Replace the O-rings. If rough idle persists, replace the solenoids entirely.", parts: ["O-Rings / Solenoids"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" } ]
