          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 or 5W-40 Synthetic (LL-01). The N46 Valvetronic system and timing chain will fail rapidly if oil changes are neglected.", parts: ["4.25L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "65 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Fuel Filter", details: "Replace the high-pressure fuel filter.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the pollen filter under the cowl.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
          ignitionAndEngine: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Timing Chain Tensioner Upgrade", details: "CRITICAL: Replace the stock tensioner with the updated, longer genuine BMW part to prevent chain slack.", parts: ["Updated Tensioner"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Timing Chain & Guides Replacement", details: "CRITICAL: The plastic guides will shatter. Replace the entire chain, guides, and sprockets proactively to save the engine.", parts: ["Febi Chain Kit"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "600 EUR" }, { interval: "120,000 km", timeLimit: "Unlimited", task: "Valve Stem Seals", details: "If the car smokes blue after idling, the seals are hardened. Replace them using specialized tools without removing the head.", parts: ["Elring Seal Kit"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "500 EUR" }, { interval: "80,000 km", timeLimit: "Unlimited", task: "Vacuum Pump Reseal", details: "Remove the mechanical vacuum pump from the rear of the head and replace the internal and external O-rings to stop oil leaking onto the exhaust.", parts: ["Elring O-Ring Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "Replace specific N46 spark plugs.", parts: ["4x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "35 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "CCV / PCV Replacement", details: "Replace the oil separator valve and all brittle plastic hoses to cure vacuum leaks and oil consumption.", parts: ["CCV Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "120 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Valve Cover Gasket", details: "Replace the complex rubber gasket, spark plug tube seals, and Valvetronic motor seal.", parts: ["Elring Gasket Set"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" } ],
          preventiveAndSuspension: [ { interval: "60,000 km", timeLimit: "8 years", task: "Front Control Arm Bushings (FCAB)", details: "CRITICAL E46 FLAW: Replace the fluid-filled FCABs with solid rubber (Meyle HD) or polyurethane to cure steering wheel shimmy under braking.", parts: ["FCAB Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Rear Trailing Arm Bushings (RTAB)", details: "Replace the massive rubber trailing arm mounts to restore rear chassis stability.", parts: ["RTAB Bushings"], importance: "High", laborDifficulty: "Expert", estimatedCost: "250 EUR" }, { interval: "Immediately", timeLimit: "Unlimited", task: "RSM Reinforcement", details: "Install steel reinforcement plates above the rear shock mounts to prevent the shocks punching through the trunk.", parts: ["Meyle HD RSMs", "Reinforcement Plates"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "V-Belts & Tensioners", details: "Replace the serpentine belts and inspect the idler pulleys.", parts: ["V-Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" } ],
