  engineeringData: { blockDesign: "Closed-deck composite block. The N51 is a specialized iteration of the N52 built exclusively to meet California/US SULEV emissions. It retains the magnesium-aluminum composite structure but features a lower compression ratio.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally smooth and well-balanced.", pistonSpeed: "14.6 m/s @ 6500 RPM.", alternator: "150A or 180A Bosch/Valeo (V-belt driven).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy. The N51 has different pistons than the N52 to lower the compression ratio to 10.0:1.", wristPinDiameter: "22 mm.", connectingRodLength: "145 mm.", rodBoltSize: "M9 (Aluminum).", crankMainJournal: "56.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.63." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for a lower 10.0:1 compression ratio.", intakePortFlow: "24-valve DOHC design. Features Valvetronic. CRITICAL DIFFERENCE: To compensate for the power lost by lowering compression, BMW fitted the N51 with the high-flow 3-stage DISA intake manifold from the factory.", valveSizes: "Intake: 34.2 mm / Exhaust: 29.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable. Controlled by Dual VANOS.", lifterType: "Hydraulic Tappets with intermediate levers for Valvetronic.", specialFeature: "SULEV Emissions Equipment. Features a specialized radiator that destroys ozone, a secondary air injection system, highly restrictive specific catalytic converters, and a permanently sealed fuel tank." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled oil pump.", thermostatOpening: "105°C Electronic map-controlled.", oilCooler: "Coolant-to-oil heat exchanger mounted to the oil filter housing." }, fuelSystem: { systemType: "Siemens MSV80 Port Injection. CRITICAL: Features a completely sealed stainless steel fuel tank with a non-replaceable internal fuel pump.", maxPressure: "3.5 Bar.", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "350 Nm (Block limits).", maxSafePowerStock: "260 hp (N/A tuning via ECU flash and headers).", maxSafeRPM: "7000 RPM (With flashed ECU).", weakestLink: "Sealed Stainless Steel Fuel Tank, EAC Radiator, Electric Water Pump, Magnesium Block Threads." }, electrical: { coils: "Individual Coil Pack system (Coil-on-Plug).", ecu: "Siemens MSV80." } },
  recommendedParts: { description: "Crucial maintenance parts to keep the highly sensitive N51 SULEV engine running and protect its delicate magnesium block.", parts: [ { category: "SULEV Radiator", brand: "Genuine BMW / Behr", note: "CRITICAL: Must have the EAC sensor integrated. Astronomically expensive. Check warranty." }, { category: "Electric Water Pump", brand: "Pierburg / VDO", note: "CRITICAL: Replace preventatively at 100k km to avoid sudden stranding." }, { category: "Oil Filter Housing Gasket", brand: "Genuine BMW", note: "CRITICAL: Fixes oil leak that will destroy the serpentine belt and engine." }, { category: "Valve Cover Gasket Set", brand: "Elring / Genuine BMW", note: "Must purchase new aluminum bolt set. Fixes oil leaks on exhaust." }, { category: "Secondary Air Injection Pump", brand: "Pierburg", note: "Common SULEV failure point causing check engine lights." }, { category: "Serpentine Belt & Tensioner", brand: "INA / Continental", note: "CRITICAL: Replace if oil from the OFHG has contaminated the belt." }, { category: "Spark Plugs", brand: "NGK LZFR6AP11G", note: "Specific N51 plugs. Replace every 60k km for optimal performance." }, { category: "Ignition Coils", brand: "Bosch / Delphi", note: "Replace proactively to cure under-load misfires." } ] },
