    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 or 5W-40 Synthetic. Regular oil changes keep the complex Valvetronic system and VANOS solenoids clean.", parts: ["6.5L 5W-40", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "75 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "Fuel Filter", timeLimit: "N/A", task: "Fuel Filter Replacement", details: "WARNING: The fuel filter on the N51 SULEV is integrated into the sealed stainless steel fuel tank and CANNOT be replaced. If it clogs, the tank must be replaced.", parts: ["Entire Fuel Tank Required"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "2000+ EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the pollen filter under the cowl.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "25 EUR" } ],
