    preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "8 years", task: "Tension Strut Bushings", details: "Replace the fluid-filled front control arm bushings with solid rubber or polyurethane to cure steering shimmy.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Rear Shock Mounts", details: "Replace the rear shock mounts; they cause clunking over bumps.", parts: ["Meyle HD RSMs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" } ],
    coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "Drain and refill the aluminum block with classic blue/green silicate-based coolant.", parts: ["8.4L G48 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Electric Water Pump & Thermostat", details: "CRITICAL: Proactively replace the Pierburg electric water pump. It WILL fail suddenly and strand you. Replace the thermostat simultaneously.", parts: ["Pierburg Water Pump", "Thermostat", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "450 EUR" }, { interval: "SULEV Radiator", timeLimit: "N/A", task: "Radiator Replacement Warning", details: "The N51 features a specific EAC radiator. If it leaks, replacement is massively expensive. Verify SULEV warranty coverage before paying out of pocket.", parts: ["SULEV Radiator"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "600+ EUR" } ],
